uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float size : 0.01 .. 0.5 = 0.1;
uniform vec3 tint : color = 1.0, 0.4, 0.2;
state fixed ph;
void update() {
  ph = fract(ph + fixed(dt) * fixed(speed));
}
vec3 shade(Led led) {
  fixed d = length(led.pos.xy);
  fixed r = fixed(0.08);
  fixed a = clamp((r - d) * fixed(20.0), fixed(0.0), fixed(1.0));
  fixed g = sin(fixed(led.uv.y) * fixed(6.28) + ph) * fixed(0.25);
  fixed b = sin(fixed(led.uv.x) * fixed(6.28) + ph + fixed(1.0)) * fixed(0.25);
  return hsv2rgb(fract(a + g + b), fixed(1.0), fixed(1.0));
}
